class Animal:
    def __init__(self, nombre):
        self.nombre = nombre

    def hablar(self):
        print("...")

class Perro(Animal):
    def hablar(self):
        print(f"{self.nombre}: Guau!")

class Gato(Animal):
    def hablar(self):
        print(f"{self.nombre}: Miau!")

# Polimorfismo
animales = [Perro("Rex"), Gato("Michi"), Perro("Fido")]

for a in animales:
    a.hablar()
